//! The engine's centre, tag and blind vocabularies.
//!
//! The observation encoder is written against the engine's state dictionary,
//! and the engine numbers a centre by sorting every key in `G.P_CENTERS`. The
//! id of a joker therefore depends on the whole table and cannot be worked out
//! from the simulator's own registries. The lists below are frozen from a
//! booted engine in `vocabulary.json` and both environments read them -- which
//! is what makes an observation from one loadable by a policy trained on the
//! other.
//!
//! The id tables are the *engine's*, not the simulator's, and they are not the
//! same. `SUIT_IDS` in `bot_api.lua` is Spades, Hearts, Clubs, Diamonds --
//! Clubs before Diamonds -- while the simulator's `Suit` enum runs Spades,
//! Hearts, Diamonds, Clubs. Mapping by enum position would silently swap the
//! two suits in every observation, which is the sort of mistake that trains a
//! policy on a game nobody is playing. The suit table lives in `state.rs`,
//! spelled out the engine's way rather than derived from the enum.
//!
//! Generated by `tools/gen_vocabulary_rs.py` from `vocabulary.json`. Do not
//! edit by hand.

use std::collections::HashMap;
use std::sync::OnceLock;

/// Key -> the 1-based id the encoder's vocabulary is built on.
///
/// The engine numbers centres by sorting every key in `G.P_CENTERS`, so the
/// id of a joker depends on the whole table and cannot be worked out from the
/// simulator's own registries. Both environments read this frozen list.
pub struct Centres {
    /// centre key -> 1-based engine id (the order of `key_list`).
    pub centre_id: HashMap<&'static str, i32>,
    /// centre key -> its set name, as `key_list` records it after the `|`.
    pub centre_set: HashMap<&'static str, &'static str>,
    /// tag key -> 1-based engine id (the order of `tag_list`).
    pub tag_id: HashMap<&'static str, i32>,
    /// blind key -> 1-based engine id (the order of `blind_list`).
    pub blind_id: HashMap<&'static str, i32>,
}

impl Centres {
    /// The centre's 1-based id, or zero for "no such value yet".
    pub fn of(&self, key: &str) -> i32 {
        *self.centre_id.get(key).unwrap_or(&0)
    }

    /// The centre's set name, or the empty string for an unknown key.
    pub fn set_of(&self, key: &str) -> &'static str {
        self.centre_set.get(key).copied().unwrap_or("")
    }

    /// The tag's 1-based id, or zero for an unknown key.
    pub fn tag(&self, key: &str) -> i32 {
        *self.tag_id.get(key).unwrap_or(&0)
    }

    /// The blind's 1-based id, or zero for an unknown key.
    pub fn blind(&self, key: &str) -> i32 {
        *self.blind_id.get(key).unwrap_or(&0)
    }
}

static CENTRES: OnceLock<Centres> = OnceLock::new();

/// The vocabulary, parsed from the frozen lists on first use.
pub fn centres() -> &'static Centres {
    CENTRES.get_or_init(build)
}

