/// Every blind key, in engine order.
pub const BLIND_LIST: &str = "bl_arm,bl_big,bl_club,bl_eye,bl_final_acorn,bl_final_bell,bl_final_heart,bl_final_leaf,bl_final_vessel,bl_fish,bl_flint,bl_goad,bl_head,bl_hook,bl_house,bl_manacle,bl_mark,bl_mouth,bl_needle,bl_ox,bl_pillar,bl_plant,bl_psychic,bl_serpent,bl_small,bl_tooth,bl_wall,bl_water,bl_wheel,bl_window";

/// Rebuild the engine's `{name: index}` maps from the frozen lists.
///
/// The split is the one `Centres.__init__` performs: `key_list` entries are
/// `key|set`, the tag and blind lists are bare comma-separated keys with the
/// empty entries skipped. Indices are 1-based.
fn build() -> Centres {
    let mut centre_id = HashMap::new();
    let mut centre_set = HashMap::new();
    for (i, entry) in KEY_LIST.split(',').enumerate() {
        let (key, set) = match entry.split_once('|') {
            Some((key, set)) => (key, set),
            None => (entry, ""),
        };
        centre_id.insert(key, i as i32 + 1);
        centre_set.insert(key, set);
    }

    let mut tag_id = HashMap::new();
    for (i, tag) in TAG_LIST.split(',').enumerate() {
        if !tag.is_empty() {
            tag_id.insert(tag, i as i32 + 1);
        }
    }

    let mut blind_id = HashMap::new();
    for (i, blind) in BLIND_LIST.split(',').enumerate() {
        if !blind.is_empty() {
            blind_id.insert(blind, i as i32 + 1);
        }
    }

    Centres {
        centre_id,
        centre_set,
        tag_id,
        blind_id,
    }
}
